INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, 'サイコロを2回振るとき、出た目の和が4以下になる確率は？', NULL, '["5/36","1/7","5/6","1/6","7/36"]', 3, '["和が4以下になるのは6通り。6/36 ＝ 1/6"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, 'サイコロを2回振るとき、出た目の積が偶数になる確率は？', NULL, '["3/7","1/4","3/4","7/9","13/18"]', 2, '["積が偶数になるのは少なくとも一方が偶数のとき。余事象（両方奇数）は9通りなので、偶数は36－9＝27通り。27/36 ＝ 3/4"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, 'コインを4回投げるとき、表がちょうど2回出る確率は？', NULL, '["5/8","3/8","7/16","5/16","3/11"]', 1, '["4回の総通り数は2⁴＝16通り。表がちょうど2回出る組み合わせは4C2＝6通り。6/16 ＝ 3/8"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, 'コインを5回投げるとき、1回も表が出ない確率は？', NULL, '["1/32","1/16","1/33","31/32","1/64"]', 0, '["5回の総通り数は2⁵＝32通り。表が1回も出ない（全て裏）のは1通り。1/32 ＝ 1/32"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '3人でじゃんけんをするとき、全員が同じ手を出す確率は？', NULL, '["4/27","2/27","1/10","8/9","1/9"]', 4, '["3人の総通り数は3³＝27通り。全員同じ手になるのは3通り。3/27 ＝ 1/9"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '3人でじゃんけんをするとき、2人だけ同じ手を出し、残り1人が異なる手を出す確率は？', NULL, '["17/27","2/5","1/3","2/3","19/27"]', 3, '["3人の総通り数は27通り。全員同じ手が3通り、全員バラバラが6通り（3!）。よって2人だけ同じ手になるのは27－3－6＝18通り。18/27 ＝ 2/3"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 独立試行の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '袋に赤玉5個、白玉4個の合計9個が入っている。この中から玉を1個取り出し、それを戻さずにもう1個取り出す。このとき、2回とも赤玉が出る確率は？', NULL, '["13/18","2/9","5/18","25/81","20/81"]', 2, '["1回目に赤玉が出る確率：5/9\n2回目に赤玉が出る確率（赤玉は残り4個、全体は8個）：4/8＝1/2\n5/9 × 1/2 ＝ 5/18"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '袋に白玉3個、黒玉5個の合計8個が入っている。この中から玉を1個取り出し、それを戻さずにもう1個取り出す。このとき、2回とも白玉が出る確率は？', NULL, '["1/14","3/28","9/64","3/32","25/28"]', 1, '["1回目に白玉が出る確率：3/8\n2回目に白玉が出る確率（白玉は残り2個、全体は7個）：2/7\n3/8 × 2/7 ＝ 6/56 ＝ 3/28"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '1から9までの数字が書かれたカードが1枚ずつ、計9枚ある。この中から1枚引いたあと戻さずにもう1枚引く。このとき、2回とも偶数が出る確率は？', NULL, '["1/6","16/81","4/27","5/6","1/8"]', 0, '["偶数のカードは2,4,6,8の4枚。\n1回目に偶数が出る確率：4/9\n2回目に偶数が出る確率（偶数は残り3枚、全体は8枚）：3/8\n4/9 × 3/8 ＝ 12/72 ＝ 1/6"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '袋に当たりくじ4本、はずれくじ8本の合計12本が入っている。この中から続けて2本引くとき（引いたくじは戻さない）、2本とも当たる確率は？', NULL, '["1/9","1/12","10/11","3/44","1/11"]', 4, '["1回目に当たりが出る確率：4/12＝1/3\n2回目に当たりが出る確率（当たりは残り3本、全体は11本）：3/11\n1/3 × 3/11 ＝ 3/33 ＝ 1/11"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '1から8までの数字が書かれたカードが1枚ずつ、計8枚ある。この中から1枚引いたあと戻さずにもう1枚引く。このとき、少なくとも1回は奇数が出る確率は？', NULL, '["5/7","1/2","4/7","11/14","3/14"]', 3, '["「少なくとも1回奇数」の余事象は「2回とも偶数」。\n偶数は2,4,6,8の4枚。\n1回目に偶数が出る確率：4/8＝1/2\n2回目に偶数が出る確率（偶数は残り3枚、全体は7枚）：3/7\n2回とも偶数になる確率：1/2×3/7＝3/14\nよって、少なくとも1回奇数が出る確率：1－3/14＝11/14"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '袋に赤玉6個、青玉4個の合計10個が入っている。この中から玉を1個取り出し、それを戻さずにもう1個取り出す。このとき、2回とも赤玉が出る確率は？', NULL, '["2/3","5/18","1/3","9/25","3/10"]', 2, '["1回目に赤玉が出る確率：6/10＝3/5\n2回目に赤玉が出る確率（赤玉は残り5個、全体は9個）：5/9\n3/5 × 5/9 ＝ 15/45 ＝ 1/3"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '袋に当たりくじ3本、はずれくじ8本の合計11本が入っている。この中から続けて2本引くとき（引いたくじは戻さない）、2本とも当たる確率は？', NULL, '["2/55","3/55","9/121","6/121","52/55"]', 1, '["1回目に当たりが出る確率：3/11\n2回目に当たりが出る確率（当たりは残り2本、全体は10本）：2/10＝1/5\n3/11 × 1/5 ＝ 3/55"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_logic', '場合の数確率', NULL, '1から7までの数字が書かれたカードが1枚ずつ、計7枚ある。この中から1枚引いたあと戻さずにもう1枚引く。このとき、少なくとも1回は偶数が出る確率は？', NULL, '["5/7","2/7","13/21","3/7","1/2"]', 0, '["「少なくとも1回偶数」の余事象は「2回とも奇数」。\n奇数は1,3,5,7の4枚。\n1回目に奇数が出る確率：4/7\n2回目に奇数が出る確率（奇数は残り3枚、全体は6枚）：3/6＝1/2\n2回とも奇数になる確率：4/7×1/2＝2/7\nよって、少なくとも1回偶数が出る確率：1－2/7＝5/7"]', 4, 'published', 'ユーザー提供のオリジナル問題（SCOA論理分野: 非復元抽出の確率 追加分）');
